 89→export function updateUser(
 90→  userId: number,
 91→  payload: Partial<{ password: string; role: UserRole; departmentCode: string | null }>,
 92→) {
 93→  const db = getDb();
 94→  const current = getUserById(userId);
 95→  if (!current) return null;
 96→
 97→  const nextPassword = payload.password ? hashPassword(payload.password) : undefined;
 98→  db.prepare(
 99→    `UPDATE users
100→     SET password = COALESCE(?, password),
101→         role = COALESCE(?, role),
102→         department_code = ?,
103→         updated_at = CURRENT_TIMESTAMP
104→     WHERE id = ?`,
105→  ).run(
106→    nextPassword ?? null,
107→    payload.role ?? null,
108→    payload.departmentCode === undefined ? current.departmentCode : payload.departmentCode,
109→    userId,
110→  );
111→
112→  return getUserById(userId);
113→}
